#include <chrono>
#include <cmath>
#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <vector>

#include <rcl_interfaces/msg/floating_point_range.hpp>
#include <rcl_interfaces/msg/parameter_descriptor.hpp>
#include <rcl_interfaces/msg/set_parameters_result.hpp>
#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

namespace bench {

// Why a rate is refused, or nothing when it is usable. The descriptor's range refuses values
// outside [0.5, 20], but a NaN passes that check, because every comparison with NaN is false.
[[nodiscard]] std::optional<std::string> rate_problem(double hz) {
  if (!std::isfinite(hz)) return "rate_hz must be a finite number";
  return std::nullopt;
}

[[nodiscard]] std::chrono::nanoseconds period_of(double hz) {
  return std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::duration<double>(1.0 / hz));
}

[[nodiscard]] rcl_interfaces::msg::ParameterDescriptor rate_descriptor() {
  rcl_interfaces::msg::FloatingPointRange range;
  range.from_value = 0.5;
  range.to_value = 20.0;
  rcl_interfaces::msg::ParameterDescriptor descriptor;
  descriptor.description = "messages per second";
  descriptor.floating_point_range.push_back(range);
  return descriptor;
}

}  // namespace bench

class Counter : public rclcpp::Node {
 public:
  explicit Counter(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("counter", options) {
    publisher_ = create_publisher<std_msgs::msg::Int64>("count", rclcpp::QoS(rclcpp::KeepLast(10)));

    // Registered before the declaration, so it also checks a value from the command line, a YAML file or a launch file.
    validate_ = add_on_set_parameters_callback([](const std::vector<rclcpp::Parameter>& changes) {
      rcl_interfaces::msg::SetParametersResult result;
      result.successful = true;
      for (const rclcpp::Parameter& p : changes) {
        if (p.get_name() != "rate_hz") continue;
        if (const std::optional<std::string> problem = bench::rate_problem(p.as_double())) {
          result.successful = false;
          result.reason = *problem;
        }
      }
      return result;
    });

    start(declare_parameter("rate_hz", 2.0, bench::rate_descriptor()));

    // Registered after the declaration, so it reacts only to changes made while the node runs.
    apply_ = add_post_set_parameters_callback([this](const std::vector<rclcpp::Parameter>& changes) {
      for (const rclcpp::Parameter& p : changes) {
        if (p.get_name() == "rate_hz") start(p.as_double());
      }
    });
  }

 private:
  void start(double hz) {
    timer_ = create_timer(bench::period_of(hz), [this] {
      std_msgs::msg::Int64 msg;
      msg.data = next_++;
      publisher_->publish(msg);
    });
    RCLCPP_INFO(get_logger(), "publishing at %.1f Hz", hz);
  }

  rclcpp::Publisher<std_msgs::msg::Int64>::SharedPtr publisher_;
  rclcpp::TimerBase::SharedPtr timer_;
  OnSetParametersCallbackHandle::SharedPtr validate_;
  PostSetParametersCallbackHandle::SharedPtr apply_;
  std::int64_t next_ = 0;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<Counter>());
  rclcpp::shutdown();
}

#include <algorithm>
#include <cinttypes>
#include <cstdint>
#include <memory>
#include <optional>
#include <vector>

#include <rcl_interfaces/msg/integer_range.hpp>
#include <rcl_interfaces/msg/parameter_descriptor.hpp>
#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

// The gap check from the topics exercise.
class SequenceCheck {
 public:
  [[nodiscard]] std::optional<std::int64_t> observe(std::int64_t value) {
    std::optional<std::int64_t> expected;
    if (last_ && value != *last_ + 1) expected = *last_ + 1;
    last_ = value;
    return expected;
  }

 private:
  std::optional<std::int64_t> last_;
};

// Picks every n-th message to log. Plain C++, so a test drives it without ROS.
class Sampler {
 public:
  void set_every(std::int64_t every) {
    every_ = std::max<std::int64_t>(every, 1);  // the descriptor allows 1 to 1000; never divide by 0
    seen_ = 0;
  }
  [[nodiscard]] bool take() { return seen_++ % every_ == 0; }

 private:
  std::int64_t every_ = 1;
  std::int64_t seen_ = 0;
};

[[nodiscard]] rcl_interfaces::msg::ParameterDescriptor report_every_descriptor() {
  rcl_interfaces::msg::IntegerRange range;
  range.from_value = 1;
  range.to_value = 1000;
  rcl_interfaces::msg::ParameterDescriptor descriptor;
  descriptor.description = "log every n-th number; gaps are always logged";
  descriptor.integer_range.push_back(range);
  return descriptor;
}

class Watcher : public rclcpp::Node {
 public:
  explicit Watcher(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("watcher", options) {
    sampler_.set_every(declare_parameter<std::int64_t>("report_every", 1, report_every_descriptor()));
    apply_ = add_post_set_parameters_callback([this](const std::vector<rclcpp::Parameter>& changes) {
      for (const rclcpp::Parameter& p : changes) {
        if (p.get_name() == "report_every") sampler_.set_every(p.as_int());
      }
    });
    subscription_ = create_subscription<std_msgs::msg::Int64>(
        "count", rclcpp::QoS(rclcpp::KeepLast(10)), [this](const std_msgs::msg::Int64& msg) { on_count(msg.data); });
  }

 private:
  void on_count(std::int64_t value) {
    if (sampler_.take()) RCLCPP_INFO(get_logger(), "heard %" PRId64, value);
    if (const std::optional<std::int64_t> expected = check_.observe(value)) {
      RCLCPP_WARN(get_logger(), "expected %" PRId64 ", got %" PRId64, *expected, value);
    }
  }

  SequenceCheck check_;
  Sampler sampler_;
  PostSetParametersCallbackHandle::SharedPtr apply_;
  rclcpp::Subscription<std_msgs::msg::Int64>::SharedPtr subscription_;  // last: its callback uses the members above
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<Watcher>());
  rclcpp::shutdown();
}
